Q: Storing values in a userdata object from lua A: <p>I'm sure that doing this has been made easier, with the new features and extensions of the Lua C API that have accrued over the over the subsequent several release/revision versions of Lua, over the last 15 years; however, nevertheless, with OP having never been able to figure out how to do this in the C API, I figured I'd take it upon myself to show anyone, that comes to this page, now or the future that this is indeed possible to do with pure C.</p>
<pre class="lang-cpp prettyprint-override"><code>// Includes omitted for brevity. 

typedef struct s_udata_handle {
    char *foo;
    char *bar;
    char *baz;
    /* arbitrary other data */
} UdataHandle_t;

int Userdata_MetatableIndexCB(lua_State *L) {
    // Check to make sure args match what is expected: 
        // - arg1 is a userdata with metatable added to registry 
        // under string index &quot;Program.Handles.UdataHandle&quot;
        // - arg2 is a string key
    UdataHandle_t *handle = luaL_checkuserdata(L, 1, &quot;Program.Handles.UdataHandle&quot;);
    const char *key = luaL_checkstring(L, 2);
    if (!strncmp(key, &quot;foo&quot;, 4)) {  // if string matches field, 
                                    // &quot;foo&quot;, perfectly, down to the null terminator:
        if (handle-&gt;foo)
            lua_pushstring(L, handle-&gt;foo);  // then push value of foo within udata 
                                             // to stack 
                                             // if and only if handle-&gt;foo!=NULL
        else
            lua_pushnil(L);  // otherwise push a nil to return.

    } else if (!strncmp(key, &quot;bar&quot;, 4)) {  // otherwise repeat process for all keys
        if (handle-&gt;bar)
            lua_pushstring(L, handle-&gt;bar);
        else
            lua_pushnil(L);

    } else if (!strncmp(key, &quot;baz&quot;, 4)) { // Obviously there are more efficient ways of 
                                        // doing this, but for posterity/proof of 
                                        // concept sake, this illustrates the point 
                                        // well enough
        if (handle-&gt;baz)
            lua_pushstring(L, handle-&gt;baz);
        else
            lua_pushnil(L);
    } else
        lua_pushnil(L);
    return 1;  // 1 = number of items at top lua state should treat as return values
}

int Userdata_MetatableNewIndexCB(lua_State *L) {
        // Check to make sure args match what is expected: 
        // - arg1 is a userdata with metatable added to registry under string index 
        // &quot;Program.Handles.UdataHandle&quot;
        // - arg2 is a string key
        // - arg3 would depend on data type the struct field that key string matches
        // is, but since all 3 struct fields in this example are strings, we 
        // can just check if it's a string.
    UdataHandle_t *handle = luaL_checkuserdata(L, 1, &quot;Program.Handles.UdataHandle&quot;);
    const char *key = luaL_checkstring(L, 2),
               *value;
    char *value_cpy;
    size_t value_len;
    value = luaL_checklstring(L, 3, &amp;value_len);  // luaL_checklstring is a function that
                                              // does the same kind of typecheck as 
                                              // luaL_checkstring does: checks if arg 
                                              // is a string, and longjumps into a 
                                              // failure case if not (it longjumps 
                                              // because that allows the lua state to 
                                              // exit this function without having to
                                              // wrap the check in a macro). The diff 
                                              // is that checklstring also gets the 
                                              // length of string and stores it at 
                                              // memblock that size_t ptr 
                                              // param3:size_t* points to.
 but also checks if 
    // Then we do the same sort of if else if check to make sure
    // string matches a struct field name:
    if (!strncmp(key, &quot;foo&quot;, 4)) {
        value_cpy = key-&gt;foo = malloc(sizeof(char)*(value_len+1));  // Include 1 byte 
                                                                    // for null 
                                                                    // terminator
        strncpy(value_cpy, value, value_len+1);
        value_cpy[value_len] = '\0';  // Manually set null term just in case because I 
                                      // cant remember if strncpy adds it or not.
    } else if (!strncmp(key, &quot;bar&quot;, 4)) {
        value_cpy = key-&gt;bar = malloc(sizeof(char)*(value_len+1));  // Include 1 byte 
                                                                    // for null 
                                                                    // terminator
        strncpy(value_cpy, value, value_len+1);
        value_cpy[value_len] = '\0';  // Manually set null term just in case because I 
                                      // cant remember if strncpy adds it or not.
    } else if (!strncmp(key, &quot;baz&quot;, 4)) {
        value_cpy = key-&gt;baz = malloc(sizeof(char)*(value_len+1));  // Include 1 byte 
                                                                    // for null 
                                                                    // terminator
        strncpy(value_cpy, value, value_len+1);
        value_cpy[value_len] = '\0';  // Manually set null term just in case because I 
                                      // cant remember if strncpy adds it or not.
    }  // No need for else case because value set is not returned by __newindex.
       // __newindex prototype stipulates that it doesnt return anything.
    return 0;
}

// Finally, since we malloc crap in our metafuncs, we need to add our own garbage collection meta method.
int Userdata_MetatableGarbageCollectionCB(lua_State *L) {
    UdataHandle_t *handle = luaL_checkuserdata(L, 1, &quot;Program.Handles.UdataHandle&quot;);
    if (handle-&gt;foo)
        free(handle-&gt;foo);
    if (handle-&gt;bar)
        free(handle-&gt;bar);
    if (handle-&gt;baz)
        free(handle-&gt;baz);
    // dont free handle itself because it's a memblock managed by lua state. 
    // handle mem block will be freed by lua garbage collector after its __gc 
    // metamethod is called upon being marked for cleaning.
}
// Since I dont wanna have to rewrite all that string malloc and copy boilerplate, but 
// still want this example to be complete and replicable, I'll write my own strdup, 
// which is itself not a std func but a compiler-specific (GCC/GNU?) extension. This 
// strdup will also take another arg for str len, and for disambiguation, will be 
// named strdupe.
static char *strdupe(const char *str, size_t len) {
    char *ret = malloc(sizeof(char)*(len+1));
    strncpy(ret, str, len+1);
    ret[len] = '\0';  // manually set null term since i cant remember if strncpy 
                      // handles that for us or not.
    return ret;
}

// The CFunction that will be available as a global for end user to create their own 
// instances of the userdata type we've created.
// Say the prototype for the C API is fun(foo : string?, bar : string?, baz : string?)
int Userdata_Create(lua_State *L)
    UDataHandle_t *handle = luaL_newuserdata(L, sizeof(UdataHandle_t));
    const char *param;
    char *param_cpy;
    size_t param_len;
    // Since all 3 params are nil-able, (nullable), we check if param is nil. If so, 
    // set associated handle struct field to NULL. Otherwise, we check if param is 
    // string before copying that string to a heap block that the MT.__gc metamethod 
    // will then free.
    if (LUA_TNIL != lua_type(L, 1)) {
        param = luaL_checklstring(L, 1, &amp;param_len);
        handle-&gt;foo = strdupe(param, param_len);
    } else {
        handle-&gt;foo = NULL;
    }
    if (LUA_TNIL != lua_type(L, 2)) {
        param = luaL_checklstring(L, 2, &amp;param_len);
        handle-&gt;bar = strdupe(param, param_len);
    } else {
        handle-&gt;bar = NULL;
    }
    if (LUA_TNIL != lua_type(L, 3)) {
        param = luaL_checklstring(L, 3, &amp;param_len);
        handle-&gt;baz = strdupe(param, param_len);
    } else {
        handle-&gt;baz = NULL;
    }
}

lua_State *Lua_Init(const char *user_script_path) {
    lua_State *L = luaL_newstate(L);
    luaL_newmetatable(L, &quot;Program.Handles.UdataHandle&quot;);
    lua_pushliteral(L, &quot;__index&quot;);
    lua_pushcfunction(L, Userdata_MetatableIndexCB);
    lua_settable(L, -3);
    lua_pushliteral(L, &quot;__newindex&quot;);
    lua_pushcfunction(L, Userdata_MetatableNewIndexCB);
    lua_settable(L, -3);
    lua_pushliteral(L, &quot;__gc&quot;);
    lua_pushcfunction(L, Userdata_MetatableGarbageCollectionCB);
    lua_settable(L, -3);
    lua_pop(L, 1);

    lua_pushcfunction(L, Userdata_Create);
    lua_setglobal(L, &quot;NewUserdata&quot;);
    if (LUA_OK!=luaL_dofile(L, user_script_path)) {
        // Handle error stuff like writing to stderr
        lua_close(L);
        return NULL;
    }
    return L;
}

int main(int argc, char *argv[]) {
    if (2!=argc) {
        fprintf(stderr, 
            &quot;[Error]: Improper cmd args. Expected usage below:\n&quot;
            &quot;\t&gt; %s &lt;lua script file path&gt;\n&quot;);
        return 1;
    }
    lua_State *L = Lua_Init(argv[1]);  // Initializes lua state and runs the 
                                       // script given in cmdline arg $1.
    lua_close(L);
    return 0;

}
</code></pre>
<p>The way this would manifest to the end user in lua is as follows in snippet below. If you were to compile above c code with appropriate lua library linkage args, and then save snippet below locally and then run</p>
<pre class="lang-bash prettyprint-override"><code>Prompt# &lt;compiled binary&gt; &lt;script file path&gt;
</code></pre>
<p>Then you would see the output would reflect that which the comments in the lua snippets below predicate:</p>
<pre class="lang-lua prettyprint-override"><code>local udata_obj = NewUserdata('hello', 'world', '!')
print(string.format(&quot;%s, %s%s&quot;, udata_obj.foo, udata_obj.bar, udata_obj.baz))
-- Prints 'hello, world!'
udata_obj.foo = 'HELLO'
udata_obj.baz = '?'
print(string.format(&quot;%s, %s%s&quot;, udata_obj.foo, udata_obj.bar, udata_obj.baz))
-- Prints 'HELLO, world?'


local failure_state1 = function() udata_obj.bar = nil end
-- Calling this function we just declared would be a program-ending failure state 
-- because of the luaL_checkstring call in the
-- CFunction that udata's metamethod, __newindex is bound to.
local failure_state2 = function() udata_obj.qux = 'lorem ipsum' end
-- Calling this function declared above would be a silent failure state 
-- because the __newindex function only checks if param2 (key) is one that 
-- matches name of a struct field, and sets said field to a copy of the string 
-- in param3 (value); however, if param2 (key) doesnt match any struct field, 
-- and UdataHandle_t::qux DNE, it simply returns without triggering a lua 
-- error. For example: if we call failure_state2 function and then try to 
-- print udata_obj.qux, it would simply print the nil returned by 
-- getmetatable(udata_obj).__index('qux'):
failure_state2()  -- function tries to set udata_obj.qux to string, 'lorem ipsum'
print(udata_obj.qux)  -- but udata_obj.qux will always yield nil due to nature of the 
                      -- __index metamethod.
-- Prints 'nil'
</code></pre>

Q: How to check if BLOB is null? A: <p>Please find below method which return that blob is empty or not</p>
<pre class="lang-java prettyprint-override"><code>private Boolean isBlobEmpty(Blob blob) {
    boolean blobFlag = false;

    try {
        if (blob == null &amp;&amp; blob.length() == 0) {
            blobFlag = true;
        }
    } catch (NullPointerException e1) {
        blobFlag = true;
        logger.debug(&quot;Error while checking blob : &quot; + e1);
    } catch (SQLException e2) {
        blobFlag = true;
        logger.debug(&quot;Error while checking blob : &quot; + e2);
    }

    return blobFlag;
}
</code></pre>

Q: In Asio, how to resume async_read / async_write after cancellation? A: <p>You start out with a bold claim (cancellation can lose data). I don't think that's true.</p>
<p>Also, you can significantly simplify your code and also allow for concurrent connections at the same time. At the root of this, I detect a C-coding style, so allow me to show C++20 style:</p>
<p><a href="https://godbolt.org/z/arorq97fr" rel="nofollow noreferrer">Live On Compiler Explorer</a></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;boost/asio.hpp&gt;
#include &lt;iostream&gt;
#include &lt;print&gt;
namespace asio = boost::asio;
using namespace std::chrono_literals;
using asio::ip::tcp;
using boost::system::error_code;

asio::awaitable&lt;void&gt; Session(tcp::socket s) try {
    error_code ec;
    auto       timed = cancel_after(5s, asio::redirect_error(ec));

    for (std::array&lt;char, 5&gt; data; !ec;) {
        auto nread = co_await async_read(s, asio::buffer(data), timed);

        if (ec == asio::error::operation_aborted) {
            std::cout &lt;&lt; &quot;timeout&quot; &lt;&lt; std::endl;
            ec.clear(); // allow loop to resume only when the error was timeout
        }

        // still handle any partial read

        if (auto payload = std::span(data).subspan(0, nread); !payload.empty()) {
            std::print(&quot;{::#02x}\n&quot;, payload);
            std::ranges::reverse(payload);

            auto nwrite = co_await async_write(s, payload /*, timed*/);
            assert(nwrite == payload.size());
        }
    }
} catch (std::exception const&amp; e) {
    std::cerr &lt;&lt; &quot;Session: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
}

asio::awaitable&lt;void&gt; Listener(uint16_t port) try {
    tcp::acceptor a(co_await asio::this_coro::executor, {{}, port});

    for (;;) {
        auto [ec, s] = co_await a.async_accept(asio::as_tuple);

        if (ec) 
            std::cout &lt;&lt; &quot;accept err:&quot; &lt;&lt; ec.message() &lt;&lt; std::endl;
        else
            co_spawn(a.get_executor(), Session(std::move(s)), asio::detached);
    }
} catch (std::exception const&amp; e) {
    std::cerr &lt;&lt; &quot;Listener: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
}

int main() {
    asio::io_context ctx;
    co_spawn(ctx, Listener(12345), asio::detached);
    ctx.run();
    std::cout &lt;&lt; &quot;Done&quot; &lt;&lt; std::endl;
}
</code></pre>
<img src="https://i.imgur.com/kA2XJxd.gif"/>
<p>If you truly want to keep the buffer and resume the read before writing any data, use a dynamic buffer:</p>
<pre class="lang-cpp prettyprint-override"><code>asio::awaitable&lt;void&gt; Session(tcp::socket s) try {
    for (std::string data;;) {
        auto [ec, nread] = co_await async_read( //
            s, asio::dynamic_buffer(data, 5), cancel_after(5s, asio::as_tuple));

        if (ec.failed()) {
            if (ec == asio::error::operation_aborted) {
                std::cout &lt;&lt; &quot;timeout&quot; &lt;&lt; std::endl;
                continue;
            } else {
                std::cout &lt;&lt; &quot;read: &quot; &lt;&lt; ec.message() &lt;&lt; std::endl;
                break;
            }
        }

        if (!data.empty()) {
            std::print(&quot;{::#02x}\n&quot;, std::span(data));
            std::ranges::reverse(data);

            auto nwrite = co_await async_write(s, asio::buffer(data));
            data.erase(0, nwrite); // effectively clear
        }
    }
} catch (std::exception const&amp; e) {
    std::cerr &lt;&lt; &quot;Session: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
}
</code></pre>
